package org.zhixiaoce.aperture;

import android.app.Activity;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Read-only 24-hour XMLTV grid. Same-window overlay keeps live playback intact. */
final class CinemaProgrammePanel {
    private final Activity activity;private final List<CinemaCatalog.Channel> channels;private final FrameLayout stage;private final LinearLayout panel,table;private final ScrollView vertical;private final HorizontalScrollView horizontal;private final LinearLayout times;private final TextView range;private final Runnable dismissed;
    private CinemaEpg guide;private int day,page;private final int hourWidth,rowHeight;private Button today,tomorrow;
    CinemaProgrammePanel(Activity a,FrameLayout stage,List<CinemaCatalog.Channel> channels,CinemaEpg guide,Runnable dismissed){activity=a;this.stage=stage;this.channels=new ArrayList<>(channels);this.guide=guide;this.dismissed=dismissed;hourWidth=TvUi.dp(a,90);rowHeight=TvUi.dp(a,48);
        panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(TvUi.dp(a,24),TvUi.dp(a,16),TvUi.dp(a,24),TvUi.dp(a,16));panel.setBackgroundColor(0xf50c1017);stage.addView(panel,new FrameLayout.LayoutParams(-1,-1));panel.setVisibility(View.GONE);
        LinearLayout controls=new LinearLayout(a);panel.addView(controls);today=TvUi.button(a,"今天",()->{day=0;render();});tomorrow=TvUi.button(a,"明天",()->{day=1;render();});controls.addView(today);controls.addView(tomorrow);Button prev=TvUi.button(a,"上一组",()->{page=Math.max(0,page-1);render();});Button next=TvUi.button(a,"下一组",()->{page=Math.min((channels.size()-1)/20,page+1);render();});controls.addView(prev);controls.addView(next);controls.addView(TvUi.button(a,"返回播放",this::hide));
        range=TvUi.text(a,"",20,true);panel.addView(range);vertical=new ScrollView(a);panel.addView(vertical,new LinearLayout.LayoutParams(-1,0,1));table=new LinearLayout(a);vertical.addView(table);times=new LinearLayout(a);times.setOrientation(LinearLayout.VERTICAL);horizontal=new HorizontalScrollView(a);horizontal.setFocusable(true);horizontal.addView(times,new ViewGroup.LayoutParams(24*hourWidth,-2));
        horizontal.setOnKeyListener((v,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN)return key>=19&&key<=22;if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){horizontal.smoothScrollBy(key==KeyEvent.KEYCODE_DPAD_RIGHT?hourWidth:-hourWidth,0);return true;}if(key==KeyEvent.KEYCODE_DPAD_DOWN){vertical.smoothScrollBy(0,rowHeight*2);return true;}if(key==KeyEvent.KEYCODE_DPAD_UP){if(vertical.getScrollY()==0)today.requestFocus();else vertical.smoothScrollBy(0,-rowHeight*2);return true;}return false;});
        for(int i=0;i<controls.getChildCount();i++){View control=controls.getChildAt(i);LinearLayout.LayoutParams spacing=new LinearLayout.LayoutParams(-2,TvUi.dp(a,44));spacing.setMargins(0,0,TvUi.dp(a,12),0);control.setLayoutParams(spacing);control.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_DPAD_DOWN){if(event.getAction()==KeyEvent.ACTION_DOWN)horizontal.requestFocus();return true;}return false;});}
        horizontal.setOnFocusChangeListener((v,focused)->{android.graphics.drawable.GradientDrawable border=new android.graphics.drawable.GradientDrawable(){@Override public void draw(android.graphics.Canvas canvas){int save=canvas.save();canvas.translate(horizontal.getScrollX(),horizontal.getScrollY());super.draw(canvas);canvas.restoreToCount(save);}};border.setColor(android.graphics.Color.TRANSPARENT);border.setCornerRadius(TvUi.dp(a,8));border.setStroke(TvUi.dp(a,2),0xfffff1d9);horizontal.setForeground(focused?border:null);});
    }
    boolean open(){return panel.getVisibility()==View.VISIBLE;}
    void show(){panel.setVisibility(View.VISIBLE);render();today.requestFocus();}
    void hide(){if(!open())return;panel.setVisibility(View.GONE);dismissed.run();}
    boolean key(KeyEvent e){if(!open())return false;if(e.getKeyCode()==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_UP)hide();return true;}return false;}
    void guide(CinemaEpg value){guide=value;if(open())render();}
    private TextView label(String text){TextView v=TvUi.text(activity,text,19,false);v.setSingleLine(true);v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setPadding(TvUi.dp(activity,8),TvUi.dp(activity,6),TvUi.dp(activity,8),0);return v;}
    private void render(){table.removeAllViews();times.removeAllViews();LinearLayout names=new LinearLayout(activity);names.setOrientation(LinearLayout.VERTICAL);table.addView(names,new LinearLayout.LayoutParams(TvUi.dp(activity,145),-2));if(horizontal.getParent()!=null)((ViewGroup)horizontal.getParent()).removeView(horizontal);table.addView(horizontal,new LinearLayout.LayoutParams(0,-2,1));Calendar calendar=Calendar.getInstance(TimeZone.getTimeZone("Asia/Shanghai"));calendar.set(Calendar.HOUR_OF_DAY,0);calendar.set(Calendar.MINUTE,0);calendar.set(Calendar.SECOND,0);calendar.set(Calendar.MILLISECOND,0);calendar.add(Calendar.DATE,day);long start=calendar.getTimeInMillis(),end=start+86400000L;java.text.SimpleDateFormat date=new java.text.SimpleDateFormat("M月d日",Locale.CHINA);date.setTimeZone(calendar.getTimeZone());range.setText(date.format(new Date(start))+" · "+(page+1)+" / "+Math.max(1,(channels.size()+19)/20)+" · 方向键浏览 · 节目以来源为准");
        names.addView(label("频道"),new LinearLayout.LayoutParams(-1,rowHeight));FrameLayout hours=new FrameLayout(activity);times.addView(hours,new LinearLayout.LayoutParams(-1,rowHeight));for(int h=0;h<24;h++){TextView text=label(String.format(Locale.ROOT,"%02d:00",h));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(hourWidth,rowHeight);p.leftMargin=h*hourWidth;hours.addView(text,p);}
        for(int index=page*20;index<Math.min(channels.size(),page*20+20);index++){CinemaCatalog.Channel channel=channels.get(index);names.addView(label(channel.name),new LinearLayout.LayoutParams(-1,rowHeight));FrameLayout line=new FrameLayout(activity);line.setBackgroundColor(index%2==0?0xff161c24:0xff111720);times.addView(line,new LinearLayout.LayoutParams(-1,rowHeight));for(CinemaEpg.Programme p:guide.programmes(channel)){if(p.stop<=start||p.start>=end)continue;int left=(int)((Math.max(start,p.start)-start)*hourWidth/3600000L),right=(int)((Math.min(end,p.stop)-start)*hourWidth/3600000L);TextView title=label(p.title);title.setContentDescription(p.title);title.setBackground(TvUi.glass(activity,false));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(Math.max(2,right-left-2),rowHeight-2);lp.leftMargin=left;line.addView(title,lp);}long now=System.currentTimeMillis();if(now>=start&&now<end){View marker=new View(activity);marker.setBackgroundColor(0xffe1cba6);FrameLayout.LayoutParams mp=new FrameLayout.LayoutParams(TvUi.dp(activity,2),rowHeight);mp.leftMargin=(int)((now-start)*hourWidth/3600000L);line.addView(marker,mp);}}
        horizontal.post(()->horizontal.scrollTo(day==0?(int)Math.max(0,(System.currentTimeMillis()-start-3600000)*hourWidth/3600000L):0,0));
    }
}
